/** Motion. Honor the system remove-animations setting: nothing moves when it is on. */
object NearAIMotion {
    const val durationFastMillis = 150
    const val durationRevealMillis = 180
    const val durationStandardMillis = 220
    const val durationSlideMillis = 250
    const val durationSlowMillis = 300
    const val durationSpinMillis = 800
    const val durationPulseMillis = 1600
    /** Small spatial moves: a switch knob, a selection indicator, a segment thumb (M3 standard fast spatial). */
    fun <T> springSpatialFast(): SpringSpec<T> = spring(dampingRatio = 0.9f, stiffness = 1400f)
    /** Default spatial moves: panes opening, sheets, popovers growing from their source (M3 standard default spatial). */
    fun <T> springSpatial(): SpringSpec<T> = spring(dampingRatio = 0.9f, stiffness = 700f)
    /** Large spatial moves: full-screen and window-level transitions (M3 standard slow spatial). */
    fun <T> springSpatialSlow(): SpringSpec<T> = spring(dampingRatio = 0.9f, stiffness = 300f)
    /** Color, opacity and blur changes that must not overshoot (M3 standard default effects). */
    fun <T> springEffects(): SpringSpec<T> = spring(dampingRatio = 1f, stiffness = 1600f)
    /** Hero moments only, one or two per product: a bouncy expressive move (M3 expressive fast spatial). */
    fun <T> springExpressive(): SpringSpec<T> = spring(dampingRatio = 0.6f, stiffness = 800f)
    /** The main-tab ember gliding between tabs (Trace: response 0.35, damping fraction 0.85). */
    fun <T> springEmber(): SpringSpec<T> = spring(dampingRatio = 0.85f, stiffness = 322f)
}

